import { useState, useEffect } from "react";
// import { useTranslation } from "react-i18next";
import API from "../api/axios";
// import toast from "react-hot-toast";
import { FaTimes, FaSync, FaTint, FaInfoCircle, FaExclamationTriangle } from "react-icons/fa";

interface AIIrrigationAdvisorModalProps {
  fieldId: string;
  fieldName: string;
  onClose: () => void;
}

interface AIResult {
  needsWater: boolean;
  urgency: string; // "Low", "Medium", "High", "Critical"
  recommendedWithinHours: number;
  waterRequirement: string;
  reason: string;
  recommendation: string;
  tips: string[];
}

interface WeatherSnapshot {
  temp: number;
  humidity: number;
  condition: string;
  windSpeed: number;
}

interface AdviceData {
  weatherSnapshot: WeatherSnapshot;
  aiResult: AIResult;
}

const AIIrrigationAdvisorModal = ({ fieldId, fieldName, onClose }: AIIrrigationAdvisorModalProps) => {
  // const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<AdviceData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const token = localStorage.getItem("token");

  const fetchAdvice = async (forceRefresh = false) => {
    setLoading(true);
    setError(null);
    try {
      const url = `/irrigation/${fieldId}${forceRefresh ? "?refresh=true" : ""}`;
      const res = await API.get(url, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.data && res.data.success) {
        setData(res.data.data);
      } else {
        setError("Failed to load advice.");
      }
    } catch (err: any) {
      setError(err.response?.data?.message || "इस समय AI सलाह उपलब्ध नहीं है। कृपया कुछ देर बाद पुनः प्रयास करें।");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAdvice();
  }, [fieldId]);

  const getUrgencyColor = (urgency: string, needsWater: boolean) => {
    if (!needsWater) return "bg-green-100 text-green-800 border-green-300";
    switch (urgency) {
      case "Critical":
      case "High":
        return "bg-red-100 text-red-800 border-red-300";
      case "Medium":
        return "bg-orange-100 text-orange-800 border-orange-300";
      case "Low":
        return "bg-yellow-100 text-yellow-800 border-yellow-300";
      default:
        return "bg-gray-100 text-gray-800 border-gray-300";
    }
  };

  const getUrgencyBadgeText = (urgency: string, needsWater: boolean) => {
    if (!needsWater) return "सिंचाई की आवश्यकता नहीं";
    switch (urgency) {
      case "Critical":
        return "तुरंत सिंचाई करें";
      case "High":
        return "जल्द सिंचाई करें";
      case "Medium":
        return "अगले 2 दिनों में सिंचाई करें";
      case "Low":
        return "सामान्य";
      default:
        return urgency;
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex justify-center items-center p-4 backdrop-blur-sm">
      <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="bg-linear-to-r from-green-600 to-green-800 p-5 text-white flex justify-between items-center relative overflow-hidden">
          {/* Subtle background pattern */}
          <div className="absolute top-0 right-0 opacity-10">
            <FaTint className="text-9xl -mt-4 -mr-4" />
          </div>

          <div className="relative z-10">
            <h2 className="text-2xl font-bold flex items-center gap-2">
              <span className="text-3xl">🌱</span> AI सिंचाई सलाह
            </h2>
            <p className="text-green-100 mt-1 opacity-90">{fieldName}</p>
          </div>
          <button 
            onClick={onClose} 
            className="relative z-10 text-white/80 hover:text-white bg-white/10 hover:bg-white/20 p-2 rounded-full transition-all cursor-pointer"
          >
            <FaTimes size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto bg-gray-50 flex-1">
          {loading ? (
            <div className="flex flex-col justify-center items-center h-48 space-y-4">
              <div className="w-12 h-12 border-4 border-green-200 border-t-green-600 rounded-full animate-spin"></div>
              <p className="text-gray-500 font-medium animate-pulse">AI आपके खेत का विश्लेषण कर रहा है...</p>
            </div>
          ) : error ? (
            <div className="bg-red-50 text-red-600 p-5 rounded-2xl flex flex-col items-center text-center border border-red-100">
              <FaExclamationTriangle className="text-4xl mb-3 text-red-400" />
              <p className="font-medium">{error}</p>
              <button 
                onClick={() => fetchAdvice(false)}
                className="mt-4 bg-red-100 hover:bg-red-200 text-red-700 px-4 py-2 rounded-xl transition-all cursor-pointer font-semibold"
              >
                पुनः प्रयास करें
              </button>
            </div>
          ) : data && data.aiResult ? (
            <div className="space-y-6">

              {/* Weather & Urgency Summary */}
              <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                <div className="flex justify-between items-center mb-4">
                  <div className={`px-4 py-1.5 rounded-full text-sm font-bold border ${getUrgencyColor(data.aiResult.urgency, data.aiResult.needsWater)}`}>
                    {getUrgencyBadgeText(data.aiResult.urgency, data.aiResult.needsWater)}
                  </div>
                  <div className="text-right text-xs text-gray-500">
                    <span className="font-medium text-gray-700">{data.weatherSnapshot.temp}°C</span> | {data.weatherSnapshot.condition}
                  </div>
                </div>

                <h3 className="text-xl font-bold text-gray-800 mb-2">
                  {data.aiResult.recommendation}
                </h3>
              </div>

              {/* Reason */}
              <div className="bg-blue-50/50 p-5 rounded-2xl border border-blue-100">
                <h4 className="flex items-center gap-2 text-blue-800 font-bold mb-2">
                  <FaInfoCircle /> कारण
                </h4>
                <p className="text-gray-700 leading-relaxed">
                  {data.aiResult.reason}
                </p>
              </div>

              {/* Tips */}
              {data.aiResult.tips && data.aiResult.tips.length > 0 && (
                <div>
                  <h4 className="font-bold text-gray-800 mb-3 px-1">सुझाव</h4>
                  <div className="space-y-2">
                    {data.aiResult.tips.map((tip, idx) => (
                      <div key={idx} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex gap-3 items-start">
                        <div className="bg-green-100 text-green-600 rounded-full w-6 h-6 flex items-center justify-center shrink-0 mt-0.5">
                          ✓
                        </div>
                        <p className="text-gray-700">{tip}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : null}
        </div>

        {/* Footer */}
        <div className="bg-white p-4 border-t border-gray-100 flex justify-between items-center">
          <p className="text-xs text-gray-400">
            सलाह केवल मार्गदर्शन के लिए है
          </p>
          <button 
            onClick={() => fetchAdvice(true)}
            disabled={loading}
            className="flex items-center gap-2 text-green-600 hover:text-green-800 bg-green-50 hover:bg-green-100 px-4 py-2 rounded-xl transition-all font-semibold disabled:opacity-50 cursor-pointer text-sm"
          >
            <FaSync className={loading ? "animate-spin" : ""} />
            {loading ? "रिफ्रेश हो रहा है..." : "नया विश्लेषण"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIIrrigationAdvisorModal;

import { useTranslation } from "react-i18next";
import {useCallback,useEffect,useState,} from "react";

import { getCachedWaterEntries } from "../utils/getCachedWaterEntries";

import {cacheWaterEntries } from "../utils/cacheWaterEntries";

import API from "../api/axios";

import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend,
} from "recharts";

interface Entry {
  _id: string;
  totalAmount: number;
  hours: number;
  date: string;
}

interface ChartData {
  month: string;
  earnings: number;
  hours: number;
}

const AnalyticsChart = () => {
  const { t } = useTranslation();
  const token = localStorage.getItem("token");

  const [chartData, setChartData] =
    useState<ChartData[]>([]);

  const [loading, setLoading] =
    useState(true);

  const [error, setError] =
    useState("");

    const buildAnalytics =
      (entries: Entry[]) => {

        const months = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];

        const currentYear = new Date().getFullYear();

        const monthlyData = months.map((month) => ({
              month,
              earnings: 0,
              hours: 0,
            })
          );

        entries.forEach(
          (entry) => {
            const entryDate = new Date(entry.date);

            if ( Number.isNaN( entryDate.getTime())) {
              return;
            }

            if ( entryDate.getFullYear() !== currentYear) {
              return;
            }

            const monthIndex = entryDate.getMonth();

            monthlyData[monthIndex].earnings +=Number(entry.totalAmount) || 0;

            monthlyData[monthIndex].hours += Number( entry.hours) || 0;
          }
        );

        setChartData(monthlyData);
    };

    //FETCH ANALYTICS

    const fetchAnalytics = useCallback(async () => {
      try {
        setLoading(true);
        setError("");

        const res =
          await API.get(
            "/water",
            {
              headers: {
                Authorization:
                  `Bearer ${token}`,
              },
            }
          );

        const entries = res.data.data || [];

        await cacheWaterEntries( entries );

        buildAnalytics( entries );

      } catch {

        const cached = await getCachedWaterEntries();

        if ( cached && cached.length > 0) {
          buildAnalytics(cached);
        } else {
          setError(t("analyticsLoadFailed"));
        }

      } finally {

        setLoading(false);

      }
    },
    [token]
  );

    useEffect(() => {
      const loadData = async () => {

          const cached = await getCachedWaterEntries();

          if (cached && cached.length > 0) {
            buildAnalytics(cached);
            setLoading(false);
          }
          fetchAnalytics();
        };

      loadData();

    }, [fetchAnalytics]);

  return (
    <div className="bg-white rounded-3xl shadow-lg p-6 mt-8">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-green-900">{t("monthlyAnalytics")}</h2>

        <p className="text-gray-500 mt-1">{t("analyticsOverview")}</p>
      </div>

      {loading && (
        <div className="h-[400px] flex items-center justify-center text-gray-500">{t("loadingAnalytics")}</div>
      )}

      {!loading && error && (
        <div className="h-[400px] flex items-center justify-center text-red-500">
          {error}
        </div>
      )}

      {!loading && !error && (
        <div className="w-full h-[400px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />

              <XAxis dataKey="month" />

              <YAxis />

              <Tooltip />

              <Legend />

              <Bar
                dataKey="earnings"
                name={t("earnings")}
                fill="#15803d"
                radius={[8, 8, 0, 0]}
              />

              <Bar
                dataKey="hours"
                name={t("hours")}
                fill="#22c55e"
                radius={[8, 8, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
};

export default AnalyticsChart;

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { FaCamera } from "react-icons/fa";
import { GiPlantRoots } from "react-icons/gi";
import { useNavigate } from "react-router-dom";
import { FaHistory } from "react-icons/fa";

import toast from "react-hot-toast";

import API from "../api/axios";


interface CropAnalysis {
  crop: string;
  problem: string;
  symptoms: string[];
  medicines: string[];
  advice: string[];
}

const CropDoctor = () => {
  const navigate = useNavigate();

  const { t } = useTranslation();

  const [image, setImage] =
    useState<File | null>(null);

  const [preview, setPreview] =
    useState<string>("");

  const [loading, setLoading] =
  useState(false);

  const [result, setResult] =
  useState<CropAnalysis | null>(
    null
  );

  const handleImageChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file =
      e.target.files?.[0];

    if (!file) return;

    setImage(file);

    setPreview(
      URL.createObjectURL(file)
    );
  };


  const handleAnalyze =
    async () => {
        if (loading) return;

        try {
        if (!image) return;

        setLoading(true);

        const formData = new FormData();

        formData.append("image", image );

        const token = localStorage.getItem("token");

        const res = await API.post('/ai/detect-pest',
            formData,
            {
                headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type":"multipart/form-data"
                },
            }
            );

        const aiData = res.data.data;

        const parsedResult: CropAnalysis = {
          crop: aiData?.crop || "",
          problem: aiData?.problem || "",
          symptoms: Array.isArray(aiData?.symptoms)
            ? aiData.symptoms
            : [],
          medicines: Array.isArray(aiData?.medicine)
            ? aiData.medicine
            : [],
          advice: Array.isArray(aiData?.advice)
            ? aiData.advice
            : [],
        };

        setResult(parsedResult);
        toast.success(t("analysisCompleted"));
      } catch (error) {
      
        toast.error(t("analysisFailed"));
      } finally {
        setLoading(false);
      }
    };

  return (
    <div
      className="
        w-full
        max-w-6xl
        mx-auto
        p-3
        sm:px-5
      "
    >
      {/* HEADER */}

      <div
        className="
          rounded-3xl
          bg-linear-to-r
          from-green-500
          to-green-800
          p-4
          sm:p-6
          text-white
          shadow-xl
          flex
          items-start justify-between
        "
      >
       <div className="flex items-center gap-4">
        <GiPlantRoots
          className="
            text-4xl
            sm:text-5xl
          "
        />

        <div>
          <h1
            className="
              text-2xl
              sm:text-3xl
              font-bold
            "
          >
            {t("cropDoctor")}
          </h1>

          <p
            className="
              text-green-100
              text-sm
              sm:text-base
              mt-2
            "
          >
            {t("cropDoctorUploadDescription")}
          </p>
        </div>
      </div>

      <button
        onClick={() =>
          navigate("/crop-history")
        }
        className="
          cursor-pointer
          flex
          items-center
          gap-2

          bg-white/20
          hover:bg-white/30

          backdrop-blur-sm

          px-4
          py-2

          rounded-xl

          text-white
          text-sm
          sm:text-base

          transition-all
        "
      >
        <FaHistory />
        <span className="hidden sm:block">
          History
        </span>
      </button>
      </div>

      {/* UPLOAD CARD */}

      <div
        className="
          mt-6
          bg-white
          rounded-3xl
          shadow-lg
          p-5
          sm:p-8
        "
      >
        <label
          className="
            cursor-pointer
            flex
            flex-col
            items-center
            justify-center
            border-2
            border-dashed
            border-green-300
            rounded-3xl
            h-64
            sm:h-80
            overflow-hidden
          "
        >
          {preview ? (
            <img
              src={preview}
              alt={t("cropImage")}
              className="
                w-full
                h-full
                object-contain
              "
            />
          ) : (
            <>
              <FaCamera
                className="
                  text-5xl
                  text-green-600
                  mb-4
                "
              />

              <p
                className="
                  text-center
                  text-gray-600
                  px-4
                "
              >
                {t("tapToUploadCropImage")}
              </p>
            </>
          )}

          <input
            type="file"
            accept="image/*"
            capture="environment"
            className="hidden"
            onChange={
              handleImageChange
            }
          />
        </label>

      
        <button
        onClick={handleAnalyze}
        disabled={
            !image || loading
        }
        className="
            mt-5
            w-full

            bg-linear-to-r
            from-green-500
            to-green-800

            text-white
            font-semibold

            py-4

            rounded-2xl

            transition-all

            hover:scale-[1.01]

            disabled:opacity-50
            disabled:cursor-not-allowed

            cursor-pointer
          "
        >
        {loading
            ? t("analyzing")
            : t("analyzeCrop")}
        </button>
      </div>

      {/* AI RESULT CARD */}

      <div
        className="
          mt-6
          bg-white
          rounded-3xl
          shadow-lg
          p-5
          sm:p-8
        "
      >
        <h2
          className="
            text-xl
            sm:text-2xl
            font-bold
            mb-5
          "
        >
          {t("analysisResult")}
        </h2>

        <div className="space-y-4">
          <div className="bg-green-50 rounded-2xl p-4">
            <p className="text-sm text-gray-500">{t("crop")}</p>
            <p className="font-semibold">{result?.crop || "-"}</p>
          </div>

          <div className="bg-red-50 rounded-2xl p-4">
            <p className="text-sm text-gray-500">{t("problem")}</p>
            <p className="font-semibold">{result?.problem || "-"}</p>
          </div>

          <div className="bg-yellow-50 rounded-2xl p-4">
            <p className="text-sm text-gray-500">{t("symptoms")}</p>
            <ul className="list-disc list-inside text-gray-700 space-y-1 mt-2">
              {result?.symptoms?.length ? (
                result.symptoms.map((symptom, index) => (
                  <li key={index}>{symptom}</li>
                ))
              ) : (
                <li>-</li>
              )}
            </ul>
          </div>

          <div className="bg-blue-50 rounded-2xl p-4">
            <p className="text-sm text-gray-500">{t("medicines")}</p>
            <ul className="list-disc list-inside text-gray-700 space-y-1 mt-2">
              {result?.medicines?.length ? (
                result.medicines.map((medicine, index) => (
                  <li key={index}>{medicine}</li>
                ))
              ) : (
                <li>-</li>
              )}
            </ul>
          </div>

          <div className="bg-slate-50 rounded-2xl p-4">
            <p className="text-sm text-gray-500">{t("advice")}</p>
            <ul className="list-disc list-inside text-gray-700 space-y-1 mt-2">
              {result?.advice?.length ? (
                result.advice.map((item, index) => (
                  <li key={index}>{item}</li>
                ))
              ) : (
                <li>-</li>
              )}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CropDoctor;

import { useEffect, useState } from "react";
import API from "../api/axios";

import toast from "react-hot-toast";
import DiseaseInsights from "./DiseaseInsights";

interface CropScanInterface {
  _id: string;
  imageUrl: string;
  crop: string;
  problem: string;
  symptoms: string[];
  medicine: string[];
  advice: string[];
  createdAt: string;
}

const CropHistory = () => {
  const [scans, setScans] = useState<CropScanInterface[]>([]);
  const [selectedScan, setSelectedScan] =
    useState<CropScanInterface | null>(null);

  const fetchHistory = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await API.get("/ai/history", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setScans(res.data.data);
    } catch (error) {
      console.log(error);
    }
  };


  const deleteScan = async ( id: string ) => {
    try {
      const token =
        localStorage.getItem(
          "token"
        );

        if (!window.confirm("Delete this scan?")) {
            return;
            }

      await API.delete(
        `/ai/history/${id}`,
        {
          headers: {
            Authorization:
              `Bearer ${token}`,
          },
        }
      );

      toast.success(
        "Scan deleted"
      );

      setScans(
        scans.filter(
          (scan) =>
            scan._id !== id
        )
      );

    } catch {

      toast.error(
        "Delete failed"
      );

    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  return (
    <div className="max-w-7xl mx-auto p-4 sm:p-6">
      <h1
        className="
          text-3xl
          font-bold
          mb-6
          bg-gradient-to-r
          from-green-500
          to-green-800
          bg-clip-text
          text-transparent
        "
      >
        🌾 Crop Scan History
      </h1>

      <DiseaseInsights scans={scans} />

      {scans.length === 0 ? (
        <div className="bg-white rounded-3xl border border-slate-200 p-10 text-center shadow-sm">
          <p className="text-gray-500">
            No crop scans found.
          </p>
        </div>
      ) : (
        <div
          className="
            grid
            grid-cols-1
            sm:grid-cols-2
            lg:grid-cols-3
            xl:grid-cols-4
            gap-5
          "
        >
          {scans.map((scan) => (
            <div
              key={scan._id}
              className="
                bg-white
                rounded-3xl
                border
                border-slate-200
                overflow-hidden
                shadow-sm
                hover:shadow-xl
                hover:-translate-y-1
                transition-all
                duration-300
              "
            >
              <div className="relative h-36 overflow-hidden bg-slate-100">
                <img
                  src={scan.imageUrl}
                  alt={scan.crop}
                  className="
                    absolute
                    inset-0
                    h-full
                    w-full
                    object-cover
                    transition-transform
                    duration-500
                    hover:scale-105
                  "
                />
              </div>

