        </div>

        {/* TEMPERATURE */}

        <div className="mt-6">

          <h1 className="text-6xl font-bold">
            {Math.round(
              weather.main.temp
            )}
            °C
          </h1>

          <p className="text-lg capitalize text-gray-200 mt-2">
