import { useTranslation } from "react-i18next";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import API from "../api/axios";

import {cacheSettings} from "../utils/cacheSettings";

import { getCachedSettings } from "../utils/getCachedSettings";

import toast from "react-hot-toast";

import {
  FaSave,
  FaSignOutAlt,
  FaUser,
} from "react-icons/fa";

const Settings = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const token =
    localStorage.getItem("token");

  const [profileLoading, setProfileLoading] =
    useState(false);

  const [formData, setFormData] =
    useState({
      name: "",
      phone: ""
    });

const fetchSettings =
  async () => {

    try {

      const res =
        await API.get(
          "/settings",
          {
            headers: {
              Authorization:
                `Bearer ${token}`,
            },
          }
        );

      const settings =
        res.data.data;

      setFormData({
        name:
          settings.name || "",
        phone:
          settings.phone || ""
      });

      await cacheSettings(
        settings
      );

    } catch {

      const cached =
        await getCachedSettings();

      if (cached) {

        setFormData({
          name:
            cached.name || "",
          phone:
            cached.phone || ""
        });

      }
    }
};

  useEffect(() => {

  const loadData =
    async () => {

      const cached =
        await getCachedSettings();

      if (cached) {

        setFormData({
          name:
            cached.name || "",
          phone:
            cached.phone || ""
        });
      }

      fetchSettings();
    };

  loadData();

}, []);
  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setFormData({
      ...formData,
      [e.target.name]:
        e.target.value,
    });
  };

  const headers = {
    Authorization: `Bearer ${token}`,
  };

  const logoutHandler = () => {
    const confirmLogout =
      window.confirm(t("logoutConfirm"));

    if (!confirmLogout) return;

    localStorage.removeItem(
      "token"
    );

    navigate("/");
  };

  const updateProfile = async (
    e: React.FormEvent
  ) => {
    e.preventDefault();

    setProfileLoading(true);

    try {
      await API.put(
        "/settings/update-profile",
        {
          name: formData.name,
          phone: formData.phone,
        },
        {
          headers,
        }
      );

      toast.success(
        t("profileUpdated")
      );

    } catch (error) {
      toast.error(
        t("profileUpdateFailed")
      );
    } finally {
      setProfileLoading(false);
    }
  };

  const inputClassName = `
    w-full
