  const cardClassName = `
    rounded-lg
    border
    border-emerald-900/10
    bg-white/75
    p-6
    shadow-sm
    backdrop-blur-xl
    sm:p-8
  `;

  const primaryButtonClassName = `
    inline-flex
    items-center
    justify-center
    gap-3
    rounded-lg
    bg-emerald-800
    px-5
    py-3.5
    font-semibold
    text-white
    shadow-sm
    transition-all
    hover:bg-emerald-700
    disabled:cursor-not-allowed
    disabled:opacity-60
    cursor-pointer
  `;

  return (
    <div className="px-3 py-4 sm:px-5 lg:px-8">

      {/* HEADER */}

      <div
        className="
          mx-auto
          max-w-6xl
          flex
          flex-col
          gap-4
          mb-2
        "
      >
        <div>

          <h1
            className="
              mt-1
              text-3xl
              font-black
              leading-tight
              text-slate-950
              sm:text-5xl
            "
          >
            {t("settings")}
          </h1>


        </div>
      </div>

      <div
        className="
          mx-auto
          max-w-6xl
          grid
          grid-cols-1
          xl:grid-cols-3
          gap-6
          mb-10
        "
      >

        <div
          className="
            xl:col-span-3
            overflow-hidden
            rounded-lg
            bg-[radial-gradient(circle_at_top_right,_rgba(104,219,169,0.35),_transparent_36%),linear-gradient(135deg,_#006948,_#002114)]
            p-6
            text-white
            shadow-xl
            sm:p-8
          "
        >

          <div
            className="
              flex
              flex-col
              gap-6
              sm:flex-row
              sm:items-center
              sm:justify-between
            "
          >

            <div className="flex flex-col gap-5 sm:flex-row sm:items-center">

              <div
                className="
                  h-20
                  w-20
                  shrink-0
                  rounded-lg
                  bg-white
                  flex
                  items-center
                  justify-center
                  text-3xl
                  font-black
                  text-emerald-800
                  shadow-lg
                "
              >
                {formData.name
                  ?.charAt(0)
                  ?.toUpperCase() || "F"}
              </div>

              <div>

                <p className="text-sm font-semibold uppercase tracking-wide text-emerald-100">{t("accountOverview")}</p>

                <h2 className="mt-1 py-1 text-3xl font-black">
                  {formData.name ||
                    t("farmer")}
                </h2>

