  // ADD / EDIT ENTRY

  const handleSubmit = async (
    e: React.FormEvent
  ) => {
    e.preventDefault();

    if (submitting) return;

    setSubmitting(true);

    try {

      if (isEditing) {
        await API.put(
          `/equipment/${editId}`,
          formData,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        toast.success(
          t("equipmentUpdated")
        );
      } else {
        await API.post(
          "/equipment",
          {
            ...formData,
            field: fieldId,
          },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        toast.success(
          t("equipmentAdded")
        );
      }

      setShowModal(false);

      setIsEditing(false);

      setEditId("");

      setFormData({
        equipmentName: "",
        amount: "",
        date: "",
      });

      await fetchEntries();

    } catch (error) {
      toast.error(
        t("operationFailed")
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (
    id: string
  ) => {
    const confirmDelete =
      window.confirm(
        t("deleteEntryConfirm")
      );

    if (!confirmDelete) return;

    if (deletingId) return;

    setDeletingId(id);

    try {
      await API.delete(
        `/equipment/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      toast.success(
        t("equipmentDeleted")
      );

      await fetchEntries();

    } catch (error) {
      toast.error(
        t("deleteFailed")
      );
    } finally {
      setDeletingId("");
    }
  };

  const handleEdit = (
    entry: EquipmentEntry
  ) => {
    setIsEditing(true);

    setEditId(entry._id);

    setFormData({
      equipmentName:
        entry.equipmentName,
      amount:
        entry.amount.toString(),
      date:
        entry.date.split("T")[0],
    });

    setShowModal(true);
  };

  // LOADING

  if (loading) {
    return (
      <div className="p-8">
        Loading...
      </div>
    );
  }

  const fieldName =
    entries[0]?.field?.name ||
    t("field");

  return (
    <div className="py-2 px-4 sm:p-4">

      {/* HEADER */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          justify-between
          sm:items-center
          gap-4
          mb-4
        "
      >

        <div>

          <h1
            className="
              text-2xl
              sm:text-3xl
              font-bold
              bg-linear-to-r
              from-green-500
              to-green-800
              bg-clip-text
              text-transparent
              py-2
            "
          >
            {t("fieldEquipmentTitle", { fieldName })}
          </h1>

          <p className="text-gray-500 mt-1">{t("manageEquipmentExpenses")}</p>

        </div>

        <button
          onClick={() =>
            setShowModal(true)
          }
          className="
            bg-linear-to-r
            from-green-500
            to-green-800
            hover:from-green-600
            hover:to-green-900
            text-white
            p-3
            rounded-2xl
            flex
            items-center
            gap-3
            font-semibold
            cursor-pointer
            transition-all
          "
        >

          <FaPlus />{t("addEquipment")}</button>

      </div>

      {/* TOTAL CARD */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          p-4
          mb-4
        "
      >

        <div className="flex items-center gap-5">

          <div
            className="
              w-20
              h-20
              rounded-full
              bg-green-100
              flex
              items-center
              justify-center
            "
          >

            <FaTractor className="text-4xl text-green-700" />

          </div>

          <div>

            <p className="text-gray-500">{t("totalEquipmentCost")}</p>

            <h2
              className="
                text-5xl
                font-bold
                bg-linear-to-r
                from-green-500
                to-green-800
                bg-clip-text
                text-transparent
                mt-2 py-2"
            >
              ₹{totalAmount}
            </h2>

          </div>

        </div>

      </div>

      {/* TABLE */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          overflow-hidden
        "
      >

        <div className="py-2 px-4 border-b">

          <h2
            className="
              text-2xl
              font-bold
              bg-linear-to-r
              from-green-500
              to-green-800
              bg-clip-text
              text-transparent
              py-2
            "
          >{t("equipmentHistory")}</h2>

        </div>

        <div className="overflow-x-auto">

          <table className="w-full">

            <thead
              className="
                bg-linear-to-r
                from-green-500
                to-green-800
                text-white
              "
            >

              <tr>

                <th className="p-3 text-left">{t("equipment")}</th>

                <th className="p-3 text-left">{t("amount")}</th>

                <th className="p-3 text-left">{t("date")}</th>

                <th className="p-3 text-left">{t("actions")}</th>

              </tr>

            </thead>

            <tbody>

              {entries.map(
                (entry) => (

                  <tr
                    key={entry._id}
                    className="
                      border-b
                      hover:bg-green-50
                      transition-all
                    "
                  >

                    <td className="p-3 font-semibold">
                      {
                        entry.equipmentName
                      }
                    </td>

                    <td
                      className="
                        p-3
                        font-bold
                        bg-linear-to-r
                        from-green-500
                        to-green-800
                        bg-clip-text
                        text-transparent
                      "
                    >
                      ₹{entry.amount}
                    </td>

                    <td className="p-3">

                      {new Date(
                        entry.date
                      ).toLocaleDateString()}

                    </td>

                    <td className="p-3">
                      <div className="flex gap-3">

                        <button
                          disabled={!!deletingId || submitting}
                          onClick={() =>
                            handleEdit(entry)
                          }
                          className="
                            bg-blue-100
                            hover:bg-blue-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                          "
                        >
                          <FaEdit className="text-blue-700" />
                        </button>

                        <button
                          disabled={!!deletingId || submitting}
                          onClick={() =>
                            handleDelete(entry._id)
                          }
                          className="
                            bg-red-100
                            hover:bg-red-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                          "
                        >
                          <FaTrash className="text-red-700" />
                        </button>

                      </div>
                    </td>

                  </tr>
                )
              )}

            </tbody>

          </table>

        </div>

      </div>

      {/* MODAL */}

{showModal && (

  <div
    className="
      fixed
      inset-0
      bg-black/50
      z-50
      flex
      justify-center
      items-center
      p-4
    "
  >

    <div
      className="
        bg-white
        rounded-3xl
        w-full
        max-w-xl
        p-8
      "
    >

      {/* HEADER */}

      <div className="mb-8">

        <h2
          className="
            text-3xl
            font-bold
            bg-linear-to-r
            from-green-500
            to-green-800
            bg-clip-text
            text-transparent py-2"
        >
          {isEditing
            ? "Edit Equipment Entry"
