        <p className="text-gray-500 mt-2">{t("addEquipmentExpenseDetails")}</p>

      </div>

      {/* FORM */}

      <form
        onSubmit={handleSubmit}
        className="space-y-5"
      >

        {/* EQUIPMENT NAME */}

        <input
          type="text"
          name="equipmentName"
          value={formData.equipmentName}
          onChange={handleChange}
          placeholder={t("equipmentName")}
          className="
            w-full
            border
            border-gray-300
            p-4
            rounded-2xl
            outline-none
            focus:border-green-700
          "
        />

        {/* AMOUNT */}

        <input
          type="number"
          name="amount"
          value={formData.amount}
          onChange={handleChange}
          placeholder={t("amount")}
          className="
            w-full
            border
            border-gray-300
            p-4
            rounded-2xl
            outline-none
            focus:border-green-700
          "
        />

        {/* DATE */}

        <input
          type="date"
          name="date"
          value={formData.date}
          onChange={handleChange}
          className="
            w-full
            border
            border-gray-300
            p-4
            rounded-2xl
            outline-none
            focus:border-green-700
          "
        />

        {/* BUTTONS */}

        <div className="flex gap-4 pt-2">

          {/* CANCEL */}

          <button
            type="button"
            disabled={submitting}
            onClick={() => {
              setShowModal(false);
              setIsEditing(false);
              setEditId("");
              setFormData({
                equipmentName: "",
                amount: "",
                date: "",
              });
            }}
            className="
              flex-1
              border
              border-gray-300
              p-4
              rounded-2xl
              font-semibold
              cursor-pointer
              disabled:opacity-60
              disabled:cursor-not-allowed
              hover:bg-gray-100
              transition-all
            "
          >{t("cancel")}</button>

          {/* SUBMIT */}

          <button
            type="submit"
            disabled={submitting}
            className="
              flex-1
              bg-linear-to-r
              from-green-500
              to-green-800
              hover:from-green-600
              hover:to-green-900
              text-white
              p-4
              rounded-2xl
              font-semibold
              cursor-pointer
              disabled:opacity-60
              disabled:cursor-not-allowed
              transition-all
            "
          >
            {submitting
              ? t("saving")
              : isEditing
                ? "Update Equipment"
                : "Add Equipment"}
          </button>

        </div>

      </form>

    </div>

  </div>
)}

    </div>
  );
};

