import React, { useEffect, useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import API from '../../api/axios';
import { generateFieldInsightsPDF } from '../../utils/generateFieldInsightsPDF';
import toast from 'react-hot-toast';

interface FieldInsight {
  _id: string;
  name: string;
  crop: string;
  area: number;
  waterExpense: number;
  fertilizerExpense: number;
  labourExpense: number;
  equipmentExpense: number;
  totalExpense: number;
  totalRevenue: number;
  netProfit: number;
  profitPerArea: number;
  createdAt: string;
}

interface FieldInsightsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const FieldInsightsModal: React.FC<FieldInsightsModalProps> = ({ isOpen, onClose }) => {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<FieldInsight[]>([]);

  // Filters
  const [selectedCrop, setSelectedCrop] = useState("All");

  useEffect(() => {
    if (isOpen) {
      fetchInsights();
    }
  }, [isOpen]);

  const fetchInsights = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      const res = await API.get("/fields/insights", {
        headers: { Authorization: `Bearer ${token}` }
      });
      setData(res.data.data);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load insights");
    } finally {
      setLoading(false);
    }
  };

  const cropsList = useMemo(() => {
    const crops = new Set<string>();
    data.forEach(f => crops.add(f.crop));
    return Array.from(crops).sort();
  }, [data]);

  const filteredData = useMemo(() => {
    if (selectedCrop === "All") return data;
    return data.filter(f => f.crop === selectedCrop);
  }, [data, selectedCrop]);

  const analytics = useMemo(() => {
    if (filteredData.length === 0) return null;

    let totalRevenue = 0;
    let totalExpenses = 0;

    let waterTotal = 0;
    let fertTotal = 0;
    let labourTotal = 0;
    let equipTotal = 0;

    const cropStats: Record<string, {count: number, revenue: number, expenses: number, profit: number}> = {};

    filteredData.forEach(f => {
      totalRevenue += f.totalRevenue;
      totalExpenses += f.totalExpense;

      waterTotal += f.waterExpense;
      fertTotal += f.fertilizerExpense;
      labourTotal += f.labourExpense;
      equipTotal += f.equipmentExpense;

      if (!cropStats[f.crop]) cropStats[f.crop] = { count: 0, revenue: 0, expenses: 0, profit: 0 };
      cropStats[f.crop].count += 1;
      cropStats[f.crop].revenue += f.totalRevenue;
      cropStats[f.crop].expenses += f.totalExpense;
      cropStats[f.crop].profit += f.netProfit;
    });

    const netProfit = totalRevenue - totalExpenses;

    const leaderboard = [...filteredData].sort((a, b) => b.netProfit - a.netProfit);
    const bestField = leaderboard.length > 0 ? leaderboard[0] : null;
    const lowestField = leaderboard.length > 0 ? leaderboard[leaderboard.length - 1] : null;

    // Recommendations logic
    const recommendations: string[] = [];
    if (bestField && bestField.netProfit > 0) {
      recommendations.push(`${bestField.name} has the highest profit. Consider expanding ${bestField.crop} cultivation in similar conditions.`);
    }

    if (lowestField && lowestField.netProfit < 0) {
      const maxExp = Math.max(lowestField.labourExpense, lowestField.waterExpense, lowestField.fertilizerExpense, lowestField.equipmentExpense);
      let expType = "";
      if (maxExp === lowestField.labourExpense) expType = "labour";
      else if (maxExp === lowestField.waterExpense) expType = "water";
      else if (maxExp === lowestField.fertilizerExpense) expType = "fertilizer";
      else expType = "equipment";

      recommendations.push(`${lowestField.name} is operating at a loss. ${expType.charAt(0).toUpperCase() + expType.slice(1)} expenses are a major factor. Evaluate cost-reduction strategies.`);
    }

    if (fertTotal > totalRevenue * 0.4 && totalRevenue > 0) {
       recommendations.push("Overall fertilizer expenses are taking up over 40% of revenue. Review fertilizer usage or explore organic alternatives.");
    }

    return {
      overview: { totalFields: filteredData.length, totalRevenue, totalExpenses, netProfit },
      bestField,
      lowestField,
      leaderboard,
      expenses: { water: waterTotal, fertilizer: fertTotal, labour: labourTotal, equipment: equipTotal },
      cropStats,
      recommendations
    };
  }, [filteredData]);

  if (!isOpen) return null;

  const handleDownloadPDF = () => {
    if (analytics) {
      generateFieldInsightsPDF(analytics);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 p-4 sm:p-6 flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-50 w-full max-w-6xl h-[95vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 bg-white border-b border-slate-200 shrink-0">
          <div>
            <h2 className="text-2xl font-bold text-green-700 flex items-center gap-2">
              {t("fieldInsightsTitle")}
            </h2>
            <p className="text-sm text-slate-500 mt-1">{t("fieldInsightsDesc")}</p>
          </div>

          <div className="flex items-center gap-3">
            <select 
              value={selectedCrop}
              onChange={e => setSelectedCrop(e.target.value)}
              className="px-4 py-2 bg-slate-100 border border-slate-200 rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-green-500"
            >
              <option value="All">{t("allCrops")}</option>
              {cropsList.map(c => <option key={c} value={c}>{c}</option>)}
            </select>

            <button 
              onClick={handleDownloadPDF}
              disabled={!analytics || loading}
              className="px-4 py-2 bg-green-600 text-white rounded-xl text-sm font-medium hover:bg-green-700 disabled:opacity-50 transition-colors"
            >
              {t("downloadPDF")}
            </button>
            <button 
              onClick={onClose}
              className="w-10 h-10 flex items-center justify-center bg-slate-100 hover:bg-slate-200 rounded-full transition-colors text-slate-600 font-bold"
            >
              ✕
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {loading ? (
            <div className="h-full flex items-center justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"></div>
            </div>
          ) : !analytics ? (
             <div className="h-full flex items-center justify-center">
               <div className="text-center p-10 bg-white rounded-3xl border border-slate-200 shadow-sm">
                 <p className="text-slate-500">{t("noFieldData")}</p>
               </div>
             </div>
          ) : (
            <div className="space-y-6">

              {/* Overview Cards */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-sm text-slate-500 font-medium">{t("totalFields")}</p>
                  <p className="text-3xl font-bold text-slate-800 mt-1">{analytics.overview.totalFields}</p>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-sm text-slate-500 font-medium">{t("totalRevenue")}</p>
                  <p className="text-2xl font-bold text-green-600 mt-1">₹{analytics.overview.totalRevenue.toLocaleString()}</p>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm">
                  <p className="text-sm text-slate-500 font-medium">{t("totalExpenses")}</p>
                  <p className="text-2xl font-bold text-red-500 mt-1">₹{analytics.overview.totalExpenses.toLocaleString()}</p>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                  <div className={`absolute right-0 top-0 w-2 h-full ${analytics.overview.netProfit >= 0 ? 'bg-green-500' : 'bg-red-500'}`}></div>
                  <p className="text-sm text-slate-500 font-medium">{t("netProfit")}</p>
                  <p className={`text-2xl font-bold mt-1 ${analytics.overview.netProfit >= 0 ? 'text-green-700' : 'text-red-600'}`}>
                    ₹{analytics.overview.netProfit.toLocaleString()}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Best / Lowest */}
                <div className="flex flex-col gap-4">
                  {analytics.bestField && (
                    <div className="bg-gradient-to-br from-green-50 to-emerald-50 p-6 rounded-3xl border border-green-100 shadow-sm flex items-center justify-between">
                      <div>
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-2xl">🏆</span>
                          <span className="bg-green-200 text-green-800 text-xs px-2 py-1 rounded-full font-bold uppercase tracking-wider">{t("topPerformer")}</span>
                        </div>
                        <h3 className="text-xl font-bold text-slate-800">{analytics.bestField.name}</h3>
                        <p className="text-sm text-slate-600">{t("crop")}: {analytics.bestField.crop}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-sm text-slate-500 mb-1">{t("netProfit")}</p>
                        <p className="text-2xl font-black text-green-600">₹{analytics.bestField.netProfit.toLocaleString()}</p>
                        {analytics.bestField.area > 0 && (
                          <p className="text-xs text-green-700 mt-1 font-medium">₹{analytics.bestField.profitPerArea.toFixed(2)}{t("unitArea")}</p>
                        )}
                      </div>
                    </div>
                  )}

                  {analytics.lowestField && (
                    <div className="bg-gradient-to-br from-red-50 to-rose-50 p-6 rounded-3xl border border-red-100 shadow-sm flex items-center justify-between">
                      <div>
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-2xl">⚠️</span>
                          <span className="bg-red-200 text-red-800 text-xs px-2 py-1 rounded-full font-bold uppercase tracking-wider">{t("needsAttention")}</span>
                        </div>
                        <h3 className="text-xl font-bold text-slate-800">{analytics.lowestField.name}</h3>
                        <p className="text-sm text-slate-600">{t("crop")}: {analytics.lowestField.crop}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-sm text-slate-500 mb-1">{t("netProfitLoss")}</p>
                        <p className={`text-2xl font-black ${analytics.lowestField.netProfit < 0 ? 'text-red-600' : 'text-slate-700'}`}>
                          ₹{analytics.lowestField.netProfit.toLocaleString()}
                        </p>
                      </div>
                    </div>
                  )}
                </div>

                {/* Recommendations */}
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <h3 className="font-bold text-lg text-slate-800 mb-4 flex items-center gap-2">
                    {t("smartRecommendations")}
                  </h3>
                  {analytics.recommendations.length > 0 ? (
                    <div className="space-y-3">
                      {analytics.recommendations.map((rec, i) => (
                        <div key={i} className="flex gap-3 bg-slate-50 p-3 rounded-2xl border border-slate-100">
                          <span className="text-blue-500 mt-0.5">•</span>
                          <p className="text-sm text-slate-700 leading-relaxed">{rec}</p>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-sm text-slate-500">{t("noRecommendations")}</p>
                  )}
                </div>
              </div>

              {/* Leaderboard & Expenses */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Leaderboard */}
                <div className="lg:col-span-2 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <h3 className="font-bold text-lg text-slate-800 mb-4 border-b pb-2">{t("fieldLeaderboard")}</h3>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="text-xs uppercase text-slate-400 border-b border-slate-100">
                          <th className="py-3 font-semibold">{t("rank")}</th>
                          <th className="py-3 font-semibold">{t("field")}</th>
                          <th className="py-3 font-semibold">{t("crop")}</th>
                          <th className="py-3 font-semibold text-right">{t("netProfit")}</th>
                          <th className="py-3 font-semibold text-right">{t("profitPerArea")}</th>
                        </tr>
                      </thead>
                      <tbody className="text-sm">
                        {analytics.leaderboard.map((field, idx) => (
                          <tr key={field._id} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                            <td className="py-3">
                              {idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : <span className="text-slate-400 font-mono ml-1">#{idx + 1}</span>}
                            </td>
                            <td className="py-3 font-medium text-slate-700">{field.name}</td>
                            <td className="py-3 text-slate-500">{field.crop}</td>
                            <td className={`py-3 text-right font-bold ${field.netProfit >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                              ₹{field.netProfit.toLocaleString()}
                            </td>
                            <td className="py-3 text-right text-slate-500">
                              {field.area > 0 ? `₹${field.profitPerArea.toFixed(2)}` : 'N/A'}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* Expenses Breakdown */}
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col">
                  <h3 className="font-bold text-lg text-slate-800 mb-4 border-b pb-2">{t("expenseBreakdown")}</h3>
                  <div className="flex-1 flex flex-col justify-center space-y-4">

                    {[
                      { label: t("water"), value: analytics.expenses.water, color: "bg-blue-400" },
                      { label: t("fertilizer"), value: analytics.expenses.fertilizer, color: "bg-emerald-400" },
                      { label: t("labour"), value: analytics.expenses.labour, color: "bg-amber-400" },
                      { label: t("equipment"), value: analytics.expenses.equipment, color: "bg-purple-400" },
                    ].map(item => {
                      const percentage = analytics.overview.totalExpenses > 0 
                        ? (item.value / analytics.overview.totalExpenses) * 100 
                        : 0;

                      return (
                        <div key={item.label}>
                          <div className="flex justify-between text-sm mb-1 text-slate-600 font-medium">
                            <span>{item.label}</span>
                            <span>₹{item.value.toLocaleString()} ({percentage.toFixed(0)}%)</span>
                          </div>
                          <div className="w-full bg-slate-100 rounded-full h-2.5 overflow-hidden">
                            <div className={`${item.color} h-2.5 rounded-full`} style={{ width: `${percentage}%` }}></div>
                          </div>
                        </div>
                      )
                    })}

                  </div>
                </div>

              </div>

              {/* Crop Profitability */}
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-lg text-slate-800 mb-4 border-b pb-2">{t("cropProfitability")}</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                  {Object.entries(analytics.cropStats).map(([crop, stats]) => (
                    <div key={crop} className="border border-slate-100 bg-slate-50 p-4 rounded-2xl flex flex-col">
                      <div className="flex justify-between items-center mb-3">
                        <h4 className="font-bold text-slate-700 flex items-center gap-1">🌾 {crop}</h4>
                        <span className="text-xs bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full font-medium">{stats.count} Fields</span>
                      </div>

                      <div className="space-y-1 mt-auto">
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-500">{t("revenue")}</span>
                          <span className="font-medium text-slate-700">₹{stats.revenue.toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span className="text-slate-500">{t("expenses")}</span>
                          <span className="font-medium text-slate-700">₹{stats.expenses.toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between text-sm pt-2 mt-1 border-t border-slate-200">
                          <span className="font-bold text-slate-600">{t("profit")}</span>
                          <span className={`font-bold ${stats.profit >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                            ₹{stats.profit.toLocaleString()}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default FieldInsightsModal;

import { useTranslation } from "react-i18next";
import {
  useEffect,
  useState,
} from "react";

import {
  useParams,
} from "react-router-dom";

import API from "../../api/axios";

import toast from "react-hot-toast";



import {
  FaTint,
  FaPlus,
  FaEdit,
  FaTrash,
} from "react-icons/fa";

interface Entry {
  _id: string;

  hours: number;

  date: string;

  field: {
    name: string;
  };
}

const FieldWater = () => {
  const { t } = useTranslation();
  const { fieldId } =
    useParams();

  const token =
    localStorage.getItem("token");

  const [entries, setEntries] =
    useState<Entry[]>([]);

  const [totalHours, setTotalHours] =
    useState(0);

  const [showModal, setShowModal] =
    useState(false);

  const [loading, setLoading] =
    useState(true);

  const [submitting, setSubmitting] =
    useState(false);

  const [deletingId, setDeletingId] =
    useState("");

  const [formData, setFormData] =
    useState({
      hours: "",
      date: "",
    });

  const [editId, setEditId] =
  useState("");

  const [isEditing, setIsEditing] =
  useState(false);

  // FETCH ENTRIES

  const fetchEntries =
    async () => {
      try {

        const res = await API.get(
          `/field-water/field/${fieldId}`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        setEntries(res.data.data);

        setTotalHours(
          res.data.totalHours
        );

      } catch (error) {
        console.log(error);
      } finally {
        setLoading(false);
      }
    };

  useEffect(() => {
    fetchEntries();
  }, []);

  // HANDLE CHANGE

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setFormData({
      ...formData,
      [e.target.name]:
        e.target.value,
    });
  };

  // ADD ENTRY

    const handleSubmit = async (
    e: React.FormEvent
    ) => {
    e.preventDefault();

    if (submitting) return;

    setSubmitting(true);

    try {

        // EDIT

        if (isEditing) {

        await API.put(
            `/field-water/${editId}`,
            formData,
            {
            headers: {
                Authorization: `Bearer ${token}`,
            },
            }
        );

        toast.success(
            t("entryUpdated")
        );

        } else {

        // CREATE

        await API.post(
            "/field-water",
            {
            ...formData,
            field: fieldId,
            },
            {
            headers: {
                Authorization: `Bearer ${token}`,
            },
            }
        );

        toast.success(
            t("entryAdded")
        );
        }

        setShowModal(false);

        setIsEditing(false);

        setEditId("");

        setFormData({
        hours: "",
        date: "",
        });

        await fetchEntries();

    } catch (error) {
        toast.error(
        t("operationFailed")
        );
    } finally {
        setSubmitting(false);
    }
    };


    const handleDelete = async (
    id: string
    ) => {
    const confirmDelete =
        window.confirm(
        t("deleteEntryConfirm")
        );

    if (!confirmDelete) return;

    if (deletingId) return;

    setDeletingId(id);

    try {

        await API.delete(
        `/field-water/${id}`,
        {
            headers: {
            Authorization: `Bearer ${token}`,
            },
        }
        );

        toast.success(
        t("entryDeleted")
        );

        await fetchEntries();

    } catch (error) {
        toast.error(
        t("deleteFailed")
        );
    } finally {
        setDeletingId("");
    }
    };

    const handleEdit = (
    entry: Entry
    ) => {

    setIsEditing(true);

    setEditId(entry._id);

    setFormData({
        hours:
        entry.hours.toString(),

        date:
        entry.date.split("T")[0],
    });

    setShowModal(true);
    };

  // LOADING

  if (loading) {
    return (
      <div className="p-8">
        Loading...
      </div>
    );
  }

  const fieldName =
    entries[0]?.field?.name ||
    t("field");

  return (
    <div className="py-2 px-4 sm:p-4">

      {/* HEADER */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          justify-between
          sm:items-center
          gap-4
          mb-4
        "
      >

        <div>

          <h1
            className="
              text-2xl
              sm:text-3xl
              font-bold
              bg-linear-to-r
              from-blue-500
              to-purple-600
              bg-clip-text
              text-transparent
              py-2
            "
          >
            {t("fieldWaterTitle", { fieldName })}
          </h1>

          <p className="text-gray-500 mt-1">{t("manageFieldWaterUsage")}</p>

        </div>

        <button
          onClick={() =>
            setShowModal(true)
          }
          className="
            bg-linear-to-r from-blue-500 to-purple-600
            hover:from-blue-600 hover:to-purple-700
            text-white
            p-3
            rounded-2xl
            flex
            items-center
            gap-3
            font-semibold
            cursor-pointer
          "
        >

          <FaPlus />{t("addWaterEntry")}</button>

      </div>

      {/* STATS */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          p-4
          mb-4
        "
      >

        <div className="flex items-center gap-5">

          <div
            className="
              w-20
              h-20
              rounded-full
              bg-blue-100
              flex
              items-center
              justify-center
            "
          >

            <FaTint className="text-blue-500 text-4xl" />

          </div>

          <div>

            <p className="text-gray-500">{t("totalWaterHours")}</p>

            <h2 className="text-5xl font-bold bg-linear-to-r from-blue-500 to-purple-600 bg-clip-text text-transparent py-2">
              {totalHours}
            </h2>

          </div>

        </div>

      </div>

      {/* TABLE */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          overflow-hidden
        "
      >

        <div className="py-2 px-4 border-b">

          <h2 className="text-2xl font-bold py-2">{t("waterHistory")}</h2>

        </div>

        <div className="overflow-x-auto">

          <table className="w-full">

            <thead
              className="
                bg-linear-to-r from-blue-500 to-purple-600 
                text-white
              "
            >

              <tr>

                <th className="p-3 text-left">{t("date")}</th>

                <th className="p-3 text-left">{t("hours")}</th>

                <th className="p-3 text-left">{t("actions")}</th>

              </tr>

            </thead>

            <tbody>

              {entries.map(
                (entry) => (

                  <tr
                    key={entry._id}
                    className="border-b"
                  >

                    <td className="p-5">

                      {new Date(
                        entry.date
                      ).toLocaleDateString()}

                    </td>

                    <td className="p-5 font-semibold">

                      {entry.hours} {t("hours")}

                    </td>

                    <td className="p-5">

                    <div className="flex gap-3">

                        {/* EDIT */}

                        <button
                        disabled={!!deletingId || submitting}
                        onClick={() =>
                            handleEdit(entry)
                        }
                        className="
                            bg-blue-100
                            hover:bg-blue-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                        "
                        >

                        <FaEdit className="text-blue-700" />

                        </button>

                        {/* DELETE */}

                        <button
                        disabled={!!deletingId || submitting}
                        onClick={() =>
                            handleDelete(entry._id)
                        }
                        className="
                            bg-red-100
                            hover:bg-red-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                        "
                        >

                        <FaTrash className="text-red-700" />

                        </button>

                    </div>

                    </td>

                  </tr>
                )
              )}

            </tbody>

          </table>

        </div>

      </div>

      {/* MODAL */}

      {showModal && (

        <div
          className="
            fixed
            inset-0
            bg-black/50
            z-50
            flex
            justify-center
            items-center
            p-4
          "
        >

          <div
            className="
              bg-white
              rounded-3xl
              w-full
              max-w-xl
              p-8
            "
          >

            <h2 className="text-3xl font-bold mb-6 py-2">
              {isEditing
                ? "Edit Water Entry"
                : "Add Water Entry"}
            </h2>

            <form
              onSubmit={
                handleSubmit
              }
              className="space-y-5"
            >

              <input
                type="number"
                name="hours"
                value={
                  formData.hours
                }
                onChange={
                  handleChange
                }
                placeholder={t("waterHours")}
                className="
                  w-full
                  border
                  p-4
                  rounded-2xl
                "
              />

              <input
                type="date"
                name="date"
                value={
                  formData.date
                }
                onChange={
                  handleChange
                }
                className="
                  w-full
                  border
                  p-4
                  rounded-2xl
                "
              />

              <div className="flex gap-4">

                <button
                  type="button"
                  disabled={submitting}
                  onClick={() =>{
                      setShowModal(false);
                      setIsEditing(false);
                      setFormData({
                        hours: "",
                        date: "",
                        });
                    }
                  }
                  className="
                    flex-1
                    border
                    p-4
                    rounded-2xl
                    font-semibold
                    cursor-pointer
                    disabled:opacity-60
                    disabled:cursor-not-allowed
                  "
                >{t("cancel")}</button>

                <button
                  type="submit"
                  disabled={submitting}
                  className="
                    flex-1
                    bg-linear-to-r from-blue-500 to-purple-600
                    hover:from-blue-600 hover:to-purple-700
                    text-white
                    p-4
                    rounded-2xl
                    font-semibold
                    cursor-pointer
                    disabled:opacity-60
                    disabled:cursor-not-allowed
                  "
                >
                  {submitting
                    ? t("saving")
                    : isEditing
                      ? t("updateEntry")
                      : t("addEntry")}
                </button>

              </div>

            </form>

          </div>

        </div>
      )}

    </div>
  );
};

export default FieldWater;

import { useTranslation } from "react-i18next";
import {
  useEffect,
  useState,
} from "react";

import {
  useNavigate,
} from "react-router-dom";

import API from "../../api/axios";

import toast from "react-hot-toast";

import { cacheFields } from "../../utils/cacheFields";
import { getCachedFields } from "../../utils/getCachedFields";
import AIIrrigationAdvisorModal from "../../components/AIIrrigationAdvisorModal";
import FieldInsightsModal from "./FieldInsightsModal";

import {
  FaTint,
  FaSeedling,
  FaTools,
  FaTractor,
  FaPlus,
  FaEdit,
  FaTrash,
} from "react-icons/fa";

interface Field {
  _id: string;

  name: string;

  area: number;

  location: string;

  crop: string;
  cropSellingPrice?: number;
  imageUrl?: string;
}

interface Analytics {
  water: number;

  fertilizer: number;

  labour: number;
  equipment: number;
  totalExpense: number;
  totalSelling?: number;
  totalQuantitySold?: number;
}


const Fields = () => {
  const { t } = useTranslation();

  const navigate = useNavigate();

  const token =
    localStorage.getItem("token");

  const [fields, setFields] =
    useState<Field[]>([]);

  const [analytics, setAnalytics] =
    useState<
      Record<string, Analytics>
    >({});

  const [loading, setLoading] =
    useState(true);

  const [submitting, setSubmitting] =
  useState(false);

  const [deletingId, setDeletingId] =
  useState("");

  const [search, setSearch] =
  useState("");

  const [showModal, setShowModal] =
    useState(false);

  const [aiModalField, setAiModalField] =
    useState<{id: string, name: string} | null>(null);

  const [showInsightsModal, setShowInsightsModal] = useState(false);

  const [isEditing, setIsEditing] =
  useState(false);

    const [editId, setEditId] =
    useState("");

  const [imageFile, setImageFile] =
    useState<File | null>(null);

  const [cropPriceEditId, setCropPriceEditId] = useState("");
  const [cropPriceInput, setCropPriceInput] = useState("");

  const [imagePreview, setImagePreview] =
    useState("");

  const [formData, setFormData] =
    useState({
      name: "",
      area: "",
      location: "",
      crop: "",
    });

  // FETCH FIELDS

  const fetchFields =
    async () => {
      try {

        const res = await API.get(
          "/fields",
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        setFields(res.data.data);

        // FETCH ANALYTICS

        const analyticsData:
          Record<
            string,
            Analytics
          > = {};

        for (const field of res.data
          .data) {

          const details =
            await API.get(
              `/fields/${field._id}`,
              {
                headers: {
                  Authorization: `Bearer ${token}`,
                },
              }
            );

          analyticsData[
            field._id
          ] =
            details.data.totals;
        }

        setAnalytics(
          analyticsData
        );

        // CACHE DATA
        await cacheFields({
          fields: res.data.data,
          analytics: analyticsData,
        });

      } catch (error) {
        console.log(error);
      } finally {
        setLoading(false);
      }
    };

  const updateCropPrice = async (fieldId: string, currentField: Field) => {
    try {
      const body = new FormData();
      body.append("name", currentField.name);
      body.append("area", currentField.area.toString());
      body.append("location", currentField.location);
      body.append("crop", currentField.crop);
      body.append("cropSellingPrice", cropPriceInput);
      
      const res = await API.put(`/fields/${fieldId}`, body, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      if (res.data.success) {
        toast.success(t("fieldUpdated") || "Price updated");
        setCropPriceEditId("");
        fetchFields(); // refresh to get new values
      }
    } catch (error) {
      console.error(error);
      toast.error(t("error") || "Error updating price");
    }
  };

  useEffect(() => {
    const loadData = async () => {
      // Load cached data first
      const cached = await getCachedFields();
      if (cached) {
        setFields(cached.fields);
        setAnalytics(cached.analytics);
        setLoading(false);
      }
      // Fetch fresh data
      fetchFields();
    };
    loadData();
  }, []);

  // HANDLE CHANGE

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setFormData({
      ...formData,
      [e.target.name]:
        e.target.value,
    });
  };

  const handleImageChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0] || null;
    setImageFile(file);

    if (file) {
      setImagePreview(
        URL.createObjectURL(file)
      );
    } else {
      setImagePreview("");
    }
  };

  // ADD FIELD

  const handleSubmit = async (
  e: React.FormEvent
) => {
  e.preventDefault();

  if (submitting) return;

  setSubmitting(true);

  try {
      const body = new FormData();
      body.append("name", formData.name);
      body.append("area", formData.area);
      body.append("location", formData.location);
      body.append("crop", formData.crop);

      if (imageFile) {
        body.append("image", imageFile);
      }

      // EDIT

      if (isEditing) {

        await API.put(
          `/fields/${editId}`,
          body,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        toast.success(
          t("fieldUpdated")
        );

      } else {

        // CREATE

        await API.post(
          "/fields",
          body,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

      toast.success(t("fieldAddedSuccessfully"));
    }

    setShowModal(false);

    setIsEditing(false);

    setEditId("");

    setFormData({
      name: "",
      area: "",
      location: "",
      crop: "",
    });
    setImageFile(null);
    setImagePreview("");

    await fetchFields();

  } catch (error) {
    toast.error(
      t("operationFailed")
    );
  } finally {
    setSubmitting(false);
  }
};

    const handleDelete = async (
  id: string
) => {
  const confirmDelete =
    window.confirm(
      t("deleteFieldConfirm")
    );

  if (!confirmDelete) return;

  if (deletingId) return;

  setDeletingId(id);

  try {

    await API.delete(
      `/fields/${id}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );

    toast.success(
      t("fieldDeleted")
    );

    await fetchFields();

  } catch (error) {
    toast.error(
      t("deleteFailed")
    );
  } finally {
    setDeletingId("");
  }
};


    const handleEdit = (
  field: Field
) => {

  setIsEditing(true);

  setEditId(field._id);

  setFormData({
    name: field.name,

    area:
      field.area.toString(),

    location:
      field.location,

    crop: field.crop,
  });

  setImageFile(null);
  setImagePreview(field.imageUrl || "");

  setShowModal(true);
};

  // LOADING

  if (loading) {
    return (
      <div className="p-8">
        Loading...
      </div>
    );
  }

  const filteredFields =
  fields.filter((field) =>
    field.name
      .toLowerCase()
      .includes(
        search.toLowerCase()
      ) ||
    field.crop
      .toLowerCase()
      .includes(
        search.toLowerCase()
      ) ||
    field.location
      .toLowerCase()
      .includes(
        search.toLowerCase()
      )
  );

  return (
    <div className="py-2 px-4 sm:p-4">

      {/* HEADER */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          justify-between
          sm:items-center
          gap-4
          mb-4
        "
      >

        <div>

          <h1
            className="
              text-2xl
              sm:text-3xl
              font-bold
              bg-linear-to-r
              from-green-500
              to-green-800
              bg-clip-text
              text-transparent
              py-2
            "
          >
            {t("apnaKhet")}
          </h1>

          <p className="text-gray-500 mt-1">{t("manageFieldsExpenses")}</p>

        </div>

        {/* BUTTONS */}

        <div className="flex flex-col sm:flex-row gap-3">
          <button
            onClick={() => setShowInsightsModal(true)}
            className="
              bg-slate-100
              hover:bg-slate-200
              text-slate-700
              p-3
              rounded-2xl
              flex
              items-center
              justify-center
              gap-3
              font-semibold
              shadow-sm
              cursor-pointer
              transition-all
              border
              border-slate-200
            "
          >
            {t("fieldInsightsBtn")}
          </button>
          <button
            onClick={() =>
              setShowModal(true)
            }
            className="
              bg-linear-to-r
              from-green-500
              to-green-800
              hover:from-green-600
              hover:to-green-900
              text-white
              p-3
              rounded-2xl
              flex
              items-center
              justify-center
              gap-3
              font-semibold
              shadow-lg
              cursor-pointer
              transition-all
            "
          >
            <FaPlus />{t("addNewField")}
          </button>
        </div>

      </div>

      {/* SEARCH */}

        <div className="mb-6">

        <input
            type="text"
            placeholder={t("searchFields")}
            value={search}
            onChange={(e) =>
            setSearch(
                e.target.value
            )
            }
            className="
            w-full
            bg-white
            border
            border-gray-300
            p-3
            rounded-3xl
            outline-none
            shadow-sm
            focus:border-green-700
            "
        />

        </div>

      {/* GRID */}

      <div
        className="
          grid
          grid-cols-1
          md:grid-cols-2
          xl:grid-cols-3
          gap-5
          mb-10
        "
      >

        {filteredFields.map(
          (field) => (

            <div
              key={field._id}
              className="
                bg-white
                rounded-3xl
                overflow-hidden
                shadow-lg
                hover:shadow-2xl
                hover:scale-[1.02]
                transition-all
                duration-300
              "
            >

              {/* IMAGE */}

              <div
                className="
                  h-56
                  relative
                  bg-cover
                  bg-center
                "
                style={{
                  backgroundImage: `url(${field.imageUrl})`,
                }}
              >
                <div
                  className="
                    absolute
                    inset-0
                    bg-black/20
                  "
                ></div>

                <div
                  className="
                    relative
                    z-10
                    p-6
                    text-white
                    h-full
                    flex
                    flex-col
                    justify-end
                  "
                >

                  <h2 className="text-4xl font-bold py-2">
                    {field.name}
                  </h2>

                  <div className="mt-2 text-lg flex items-center gap-2">
                    <span>{field.crop}</span>
                    {cropPriceEditId === field._id ? (
                      <div className="flex items-center gap-1 bg-white/20 px-2 py-1 rounded-lg">
                        <span className="text-sm">₹</span>
                        <input
                          type="number"
                          autoFocus
                          value={cropPriceInput}
                          onChange={(e) => setCropPriceInput(e.target.value)}
                          className="w-16 bg-transparent text-white outline-none text-sm"
                          placeholder="Price"
                        />
                        <button
                          onClick={() => updateCropPrice(field._id, field)}
                          className="text-green-300 hover:text-green-200"
                        >
                          ✓
                        </button>
                        <button
                          onClick={() => setCropPriceEditId("")}
                          className="text-red-300 hover:text-red-200 text-xs ml-1"
                        >
                          ✕
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span className="text-sm bg-black/30 px-2 py-0.5 rounded-md">₹{field.cropSellingPrice || 0}/Q</span>
                        <button
                          onClick={() => {
                            setCropPriceEditId(field._id);
                            setCropPriceInput(field.cropSellingPrice?.toString() || "");
                          }}
                          className="text-gray-300 hover:text-white cursor-pointer"
                        >
                          <FaEdit size={14} />
                        </button>
                      </div>
                    )}
                  </div>

                  <p className="mt-1 text-sm text-gray-200">
                    {field.location}
                  </p>


                  <div className="flex gap-4 mt-5">
                    {/* EDIT */}

                    <button
                        disabled={!!deletingId || submitting}
                        onClick={() =>
                        handleEdit(field)
                        }
                        className="
                        flex-1
                        bg-blue-100
                        hover:bg-blue-200
                        text-blue-700
                        p-3
                        rounded-2xl
                        flex
                        justify-center
                        items-center
                        gap-2
                        font-semibold
                        cursor-pointer
                        disabled:opacity-60
                        disabled:cursor-not-allowed
                        transition-all
                        "
                    >

                        <FaEdit />{t("edit")}</button>

                    {/* DELETE */}

                    <button
                        disabled={!!deletingId || submitting}
                        onClick={() =>
                        handleDelete(field._id)
                        }
                        className="
                        flex-1
                        bg-red-100
                        hover:bg-red-200
                        text-red-700
                        p-3
                        rounded-2xl
                        flex
                        justify-center
                        items-center
                        gap-2
                        font-semibold
                        cursor-pointer
                        disabled:opacity-60
                        disabled:cursor-not-allowed
                        transition-all
                        "
                    >

                        <FaTrash />{t("delete")}</button>

                    </div>

                </div>

              </div>

              {/* BODY */}

              <div className="py-3 px-4">

                {/* TOP */}

                <div
                  className="
                    flex
                    justify-between
                    items-center
                    mb-2
                  "
                >

                  <h3
                    className="
                      text-xl
                      font-bold
                      bg-linear-to-r
                      from-green-500
                      to-green-800
                      bg-clip-text
                      text-transparent py-2"
                  >{t("costModules")}</h3>

                  <div
                    className="
                      bg-green-100
                      text-green-900
                      px-4
                      py-2
                      rounded-xl
                      font-bold
                    "
                  >
                    {field.area} m&sup2;
                  </div>

                </div>

                {/* MODULES */}

                <div
                  className="
                    grid
                    grid-cols-2
                    gap-2
                  "
                >

                  {/* WATER */}

                  <button
                    onClick={() =>
                      navigate(
                        `/field-water/${field._id}`
                      )
                    }
                    className="
                      bg-blue-50
                      hover:bg-blue-100
                      border
                      border-blue-100
                      rounded-2xl
                      p-3
                      text-left
                      transition-all
                      cursor-pointer
                    "
                  >

                    <div className="flex justify-between items-end">
                      <FaTint className="text-blue-600 text-2xl mb-2" />
                      <p className="text-lg font-bold text-blue-900 mt-1">₹{analytics[field._id]?.water || 0}</p>
                    </div>

                    <p className="font-semibold text-blue-900">{t("water")}</p>

                  </button>

                  {/* FERTILIZER */}

                  <button
                    onClick={() =>
                      navigate(
                        `/fertilizers/${field._id}`
                      )
                    }
                    className="
                      bg-green-50
                      hover:bg-green-100
                      border
                      border-green-100
                      rounded-2xl
                      p-3
                      text-left
                      transition-all
                      cursor-pointer
                    "
                  >

                    <div className="flex justify-between items-end">
                      <FaSeedling className="text-green-600 text-2xl mb-2" />
                      <p className="text-lg font-bold text-green-900 mt-1">₹{analytics[field._id]?.fertilizer || 0}</p>
                    </div>

                    <p className="font-semibold text-green-900">{t("fertilizer")}</p>

                  </button>

                  {/* LABOUR */}

                  <button
                    onClick={() =>
                      navigate(
                        `/labour/${field._id}`
                      )
                    }
                    className="
                      bg-yellow-50
                      hover:bg-yellow-100
                      border
                      border-yellow-100
                      rounded-2xl
                      p-3
                      text-left
                      transition-all
                      cursor-pointer
                    "
                  >

                    <div className="flex justify-between items-end">
                      <FaTools className="text-yellow-600 text-2xl mb-2" />
                      <p className="text-lg font-bold text-yellow-900 mt-1">₹{analytics[field._id]?.labour || 0}</p>
                    </div>

                    <p className="font-semibold text-yellow-900">{t("labour")}</p>

                  </button>

                  {/* EQUIPMENT */}

                  <button
                    onClick={() =>
                      navigate(
                        `/equipment/${field._id}`
                      )
                    }
                    className="
                      bg-gray-100
                      hover:bg-gray-200
                      border
                      border-gray-200
                      rounded-2xl
                      p-3
                      text-left
                      transition-all
                      cursor-pointer
                    "
                  >

                    <div className="flex justify-between items-end">
                      <FaTractor className="text-gray-700 text-2xl mb-2" />
                      <p className="text-lg font-bold text-gray-900 mt-1">₹{analytics[field._id]?.equipment || 0}</p>
                    </div>

                    <p className="font-semibold text-gray-900">{t("equipment")}</p>

                  </button>

                </div>

                {/* PROFIT SUMMARY */}

                <div
                  className="
                    mt-3
                    rounded-3xl
                    bg-white
                    border border-gray-100
                    p-4
                    shadow-sm
                  "
                >

                  <div className="flex justify-between items-center text-sm font-medium text-gray-500 mb-1">
                    <span>Expense</span>
                    <span>₹{analytics[field._id]?.totalExpense || 0}</span>
                  </div>

                  <div className="flex justify-between items-center text-sm font-medium text-gray-500 mb-2">
                    <span>Selling</span>
                    <span>₹{analytics[field._id]?.totalSelling || 0}</span>
                  </div>

                  <div className="pt-2 border-t border-gray-100 flex justify-between items-center">
                    <span className="font-bold text-gray-800">Profit / Loss</span>
                    
                    {(() => {
                      const profit = (analytics[field._id]?.totalSelling || 0) - (analytics[field._id]?.totalExpense || 0);
                      const hasSale = (analytics[field._id]?.totalSelling || 0) > 0;
                      
                      if (!hasSale) {
                        return <span className="bg-orange-100 text-orange-800 px-3 py-1 rounded-lg text-sm font-bold">No Sale Yet</span>;
                      }
                      
                      if (profit >= 0) {
                        return <span className="bg-green-100 text-green-800 px-3 py-1 rounded-lg text-sm font-bold flex items-center gap-1">🟢 ₹{profit}</span>;
                      } else {
                        return <span className="bg-red-100 text-red-800 px-3 py-1 rounded-lg text-sm font-bold flex items-center gap-1">🔴 ₹{Math.abs(profit)}</span>;
                      }
                    })()}
                  </div>

                </div>

                {/* CROP SALE RECEIPTS BUTTON */}
                <button
                  onClick={() => navigate(`/crop-sales/${field._id}`)}
                  className="mt-2 w-full bg-linear-to-r from-emerald-100 to-emerald-200 hover:from-emerald-200 hover:to-emerald-300 border border-emerald-300 text-emerald-900 p-3 rounded-2xl flex justify-center items-center gap-2 font-semibold shadow-sm transition-all cursor-pointer"
                >
                  <span className="text-xl">🌾</span> Crop Sale Receipts
                </button>

                {/* ACTIONS */}
                <div className="mt-4">
                  <button
                    onClick={() => setAiModalField({ id: field._id, name: field.name })}
                    className="w-full bg-linear-to-r from-green-600 to-green-800 hover:from-green-700 hover:to-green-900 text-white p-3 rounded-2xl flex justify-center items-center gap-2 font-bold shadow-md hover:shadow-lg transition-all cursor-pointer"
                  >
                    <span className="text-xl">🌱</span> AI सिंचाई सलाह
                  </button>
                </div>


              </div>

            </div>
          )
        )}

      </div>

      {/* MODAL */}

      {showModal && (

        <div
          className="
            fixed
            inset-0
            bg-black/50
            z-50
            flex
            justify-center
            items-center
            p-4
          "
        >

          <div
            className="
              bg-white
              rounded-3xl
              w-full
              
              max-w-2xl
              p-8
            "
          >

            {/* HEADER */}

            <div className="mb-4">

              <h2
                className="
                  text-3xl
                  font-bold
                  bg-linear-to-r
                  from-green-500
                  to-green-800
                  bg-clip-text
                  text-transparent py-2"
              >
                {isEditing
                    ? t("editField")
                    : t("addNewField")}
              </h2>

              <p className="text-gray-500 mt-2">{t("createFarmingField")}</p>

            </div>

            {/* FORM */}

            <form
              onSubmit={
                handleSubmit
              }
              className="space-y-1"
            >

              <input
                type="text"
                name="name"
                value={
                  formData.name
                }
                onChange={
                  handleChange
                }
                placeholder={t("fieldName")}
                className="
                  w-full
                  border
                  border-gray-300
                  p-4
                  rounded-2xl
                  outline-none
                "
              />

              <input
                type="number"
                name="area"
                value={
                  formData.area
                }
                onChange={
                  handleChange
                }
                placeholder={t("areametersq")}
                className="
                  w-full
                  border
                  border-gray-300
                  p-4
                  rounded-2xl
                  outline-none
                "
              />

              <input
                type="text"
                name="location"
                value={
                  formData.location
                }
                onChange={
                  handleChange
                }
                placeholder={t("location")}
                className="
                  w-full
                  border
                  border-gray-300
                  p-4
                  rounded-2xl
                  outline-none
                "
              />

              <input
                type="text"
                name="crop"
                value={
                  formData.crop
                }
                onChange={
                  handleChange
                }
                placeholder={t("currentCrop")}
                className="
                  w-full
                  border
                  border-gray-300
                  p-4
                  rounded-2xl
                  outline-none
                "
              />

              <label className="block">
                <span className="text-sm font-medium text-gray-700">
                  {t("fieldImage")}
                </span>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="
                    mt-2
                    w-full
                    border
                    border-gray-300
                    rounded-2xl
                    p-3
                    bg-white
                    outline-none
                  "
                />
              </label>

              {imagePreview && (
                <div className="mt-3">
                  <p className="text-sm text-gray-600 mb-2">
                    {t("previewImage")}
                  </p>
                  <img
                    src={imagePreview}
                    alt={t("fieldImage")}
                    className="
                      w-30
                      
                      object-cover
                      rounded-3xl
                      border
                      border-gray-200
                    "
                  />
                </div>
              )}

              {/* BUTTONS */}

              <div className="flex gap-4 pt-2">

                <button
                  type="button"
                  disabled={submitting}
                  onClick={() =>{
                    setShowModal(false);
                    setIsEditing(false);
                    setFormData({
                        name: "",
                        area: "",
                        location: "",
                        crop: "",
                        });
                    setImageFile(null);
                    setImagePreview("");
                    }
                  }
                  className="
                    flex-1
                    border
                    border-gray-300
                    p-4
                    rounded-2xl
                    font-semibold
                    cursor-pointer
                    disabled:opacity-60
                    disabled:cursor-not-allowed
                    hover:bg-gray-100
                    transition-all
                  "
                >{t("cancel")}</button>

                <button
                  type="submit"
                  disabled={submitting}
                  className="
                    flex-1
                    bg-linear-to-r
                    from-green-500
                    to-green-800
                    hover:from-green-600
                    hover:to-green-900
                    text-white
                    p-4
                    rounded-2xl
                    font-semibold
                    cursor-pointer
                    disabled:opacity-60
                    disabled:cursor-not-allowed
                    transition-all
                  "
                >
                  {submitting
                    ? t("saving")
                    : isEditing
                      ? t("updateField")
                      : t("addField")}
                </button>

              </div>

            </form>

          </div>

        </div>
      )}
      {/* AI Modal */}
      {aiModalField && (
        <AIIrrigationAdvisorModal
          fieldId={aiModalField.id}
          fieldName={aiModalField.name}
          onClose={() => setAiModalField(null)}
        />
      )}

      {/* Field Insights Modal */}
      <FieldInsightsModal 
        isOpen={showInsightsModal} 
        onClose={() => setShowInsightsModal(false)} 
      />

    </div>
  );
};

export default Fields;

import { useTranslation } from "react-i18next";
import {
  useEffect,
  useState,
} from "react";

import {
  useParams,
} from "react-router-dom";

import API from "../../api/axios";

import toast from "react-hot-toast";

import {
  FaTools,
  FaPlus,
  FaEdit,
  FaTrash,
} from "react-icons/fa";

interface LabourEntry {
  _id: string;

  amount: number;

  workType: string;

  date: string;

  field: {
    name: string;
  };
}

const Labour = () => {
  const { t } = useTranslation();
  const { fieldId } =
    useParams();

  const token =
    localStorage.getItem("token");

  const [entries, setEntries] =
    useState<LabourEntry[]>([]);

  const [totalAmount, setTotalAmount] =
    useState(0);

  const [loading, setLoading] =
    useState(true);

  const [submitting, setSubmitting] =
    useState(false);

  const [deletingId, setDeletingId] =
    useState("");

  const [showModal, setShowModal] =
    useState(false);

  const [formData, setFormData] =
    useState({
      amount: "",
      workType: "",
      date: "",
    });

  const [editId, setEditId] =
    useState("");

  const [isEditing, setIsEditing] =
    useState(false);

  // FETCH LABOUR

  const fetchEntries =
    async () => {
      try {

        const res = await API.get(
          `/labour/field/${fieldId}`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        setEntries(res.data.data);

        setTotalAmount(
          res.data.totalAmount
        );

      } catch (error) {
        console.log(error);
      } finally {
        setLoading(false);
      }
    };

  useEffect(() => {
    fetchEntries();
  }, []);

  // HANDLE CHANGE

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setFormData({
      ...formData,
      [e.target.name]:
        e.target.value,
    });
  };

  // ADD / EDIT ENTRY

  const handleSubmit = async (
    e: React.FormEvent
  ) => {
    e.preventDefault();

    if (submitting) return;

    setSubmitting(true);

    try {

      if (isEditing) {
        await API.put(
          `/labour/${editId}`,
          formData,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        toast.success(
          t("labourUpdated")
        );
      } else {
        await API.post(
          "/labour",
          {
            ...formData,
            field: fieldId,
          },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        toast.success(
          t("labourAddedSuccessfully")
        );
      }

      setShowModal(false);

      setIsEditing(false);

      setEditId("");

      setFormData({
        amount: "",
        workType: "",
        date: "",
      });

      await fetchEntries();

    } catch (error) {
      toast.error(
        t("operationFailed")
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (
    id: string
  ) => {
    const confirmDelete =
      window.confirm(
        t("deleteEntryConfirm")
      );

    if (!confirmDelete) return;

    if (deletingId) return;

    setDeletingId(id);

    try {
      await API.delete(
        `/labour/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      toast.success(
        t("labourDeleted")
      );

      await fetchEntries();

    } catch (error) {
      toast.error(
        t("deleteFailed")
      );
    } finally {
      setDeletingId("");
    }
  };

  const handleEdit = (
    entry: LabourEntry
  ) => {
    setIsEditing(true);

    setEditId(entry._id);

    setFormData({
      amount:
        entry.amount.toString(),
      workType:
        entry.workType,
      date:
        entry.date.split("T")[0],
    });

    setShowModal(true);
  };

  // LOADING

  if (loading) {
    return (
      <div className="p-8">
        Loading...
      </div>
    );
  }

  const fieldName =
    entries[0]?.field?.name ||
    t("field");

  return (
    <div className="py-2 px-4 sm:p-4">

      {/* HEADER */}

      <div
        className="
          flex
          flex-col
          sm:flex-row
          justify-between
          sm:items-center
          gap-4
          mb-4
        "
      >

        <div>

          <h1
            className="
              text-2xl
              sm:text-3xl
              font-bold
              bg-linear-to-r
              from-green-500
              to-green-800
              bg-clip-text
              text-transparent
              py-2
            "
          >
            {t("fieldLabourTitle", { fieldName })}
          </h1>

          <p className="text-gray-500 mt-1">{t("manageLabourExpenses")}</p>

        </div>

        <button
          onClick={() =>
            setShowModal(true)
          }
          className="
            bg-linear-to-r
            from-green-500
            to-green-800
            hover:from-green-600
            hover:to-green-900
            text-white
            p-3
            rounded-2xl
            flex
            items-center
            gap-3
            font-semibold
            cursor-pointer
            transition-all
          "
        >

          <FaPlus />{t("addLabour")}</button>

      </div>

      {/* TOTAL CARD */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          p-4
          mb-4
          hover:shadow-2xl
          transition-all
        "
      >

        <div className="flex items-center gap-5">

          {/* ICON */}

          <div
            className="
              w-20
              h-20
              rounded-full
              bg-green-100
              flex
              items-center
              justify-center
            "
          >

            <FaTools className="text-4xl text-green-700" />

          </div>

          {/* CONTENT */}

          <div>

            <p className="text-gray-500">{t("totalLabourCost")}</p>

            <h2
              className="
                text-5xl
                font-bold
                bg-linear-to-r
                from-green-500
                to-green-800
                bg-clip-text
                text-transparent
                mt-2 py-2"
            >
              ₹{totalAmount}
            </h2>

          </div>

        </div>

      </div>

      {/* HISTORY */}

      <div
        className="
          bg-white
          rounded-3xl
          shadow-lg
          overflow-hidden
        "
      >

        {/* HEADER */}

        <div className="py-2 px-4 border-b">

          <h2
            className="
              text-2xl
              font-bold
              bg-linear-to-r
              from-green-500
              to-green-800
              bg-clip-text
              text-transparent
              py-2
            "
          >{t("labourHistory")}</h2>

        </div>

        {/* TABLE */}

        <div className="overflow-x-auto">

          <table className="w-full">

            <thead
              className="
                bg-linear-to-r
                from-green-500
                to-green-800
                text-white
              "
            >

              <tr>

                <th className="p-3 text-left">{t("workType")}</th>

                <th className="p-3 text-left">{t("amount")}</th>

                <th className="p-3 text-left">{t("date")}</th>

                <th className="p-3 text-left">{t("actions")}</th>

              </tr>

            </thead>

            <tbody>

              {entries.map(
                (entry) => (

                  <tr
                    key={entry._id}
                    className="
                      border-b
                      hover:bg-green-50
                      transition-all
                    "
                  >

                    {/* WORK TYPE */}

                    <td className="p-3 font-semibold">

                      {entry.workType}

                    </td>

                    {/* AMOUNT */}

                    <td
                      className="
                        p-3
                        font-bold
                        bg-linear-to-r
                        from-green-500
                        to-green-800
                        bg-clip-text
                        text-transparent
                      "
                    >

                      ₹{entry.amount}

                    </td>

                    {/* DATE */}

                    <td className="p-3">

                      {new Date(
                        entry.date
                      ).toLocaleDateString()}

                    </td>

                    <td className="p-3">
                      <div className="flex gap-3">

                        <button
                          disabled={!!deletingId || submitting}
                          onClick={() =>
                            handleEdit(entry)
                          }
                          className="
                            bg-blue-100
                            hover:bg-blue-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                          "
                        >
                          <FaEdit className="text-blue-700" />
                        </button>

                        <button
                          disabled={!!deletingId || submitting}
                          onClick={() =>
                            handleDelete(entry._id)
                          }
                          className="
                            bg-red-100
                            hover:bg-red-200
                            p-3
                            rounded-xl
                            cursor-pointer
                            disabled:opacity-60
                            disabled:cursor-not-allowed
                            transition-all
                          "
                        >
                          <FaTrash className="text-red-700" />
                        </button>

                      </div>
                    </td>

                  </tr>
                )
              )}

            </tbody>

          </table>

        </div>

      </div>

      {/* MODAL */}

      {showModal && (

        <div
          className="
            fixed
            inset-0
            bg-black/50
