import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export interface DetailedWaterEntry {
  date: string;
  hours: number;
  totalAmount: number;
  waterRate?: number;
  notes?: string;
}

export interface FarmerReportData {
  farmer: {
    _id: string;
    name: string;
    phone?: string;
  };
  totalHours: number;
  totalAmount: number;
  totalEntries: number;
  entries: DetailedWaterEntry[];
}

const generateFarmerReportPDF = (data: FarmerReportData) => {
  const doc = new jsPDF();

  // Header Title
  doc.setFontSize(22);
  doc.setTextColor(6, 78, 59); // emerald-900
  doc.text("Smart Kisan", 14, 20);

  doc.setFontSize(16);
  doc.setTextColor(4, 120, 87); // emerald-700
  doc.text("Water Usage Report", 14, 28);

  // Farmer Details
  doc.setFontSize(12);
  doc.setTextColor(15, 23, 42); // slate-900
  doc.text(`Farmer Name: ${data.farmer.name}`, 14, 40);
  if (data.farmer.phone) {
    doc.text(`Phone Number: ${data.farmer.phone}`, 14, 47);
  }
  doc.text(
    `Generated Date: ${new Date().toLocaleDateString("en-IN")}`,
    14,
    data.farmer.phone ? 54 : 47
  );

  // Summary Section
  const startY = data.farmer.phone ? 64 : 57;

  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Summary", 14, startY);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(11);
  doc.text(`Total Hours: ${data.totalHours.toFixed(1)} h`, 14, startY + 7);
  doc.text(`Total Cost: Rs ${data.totalAmount.toFixed(2)}`, 70, startY + 7);
  doc.text(`Total Entries: ${data.totalEntries}`, 140, startY + 7);

  // Entries Table
  autoTable(doc, {
    startY: startY + 15,
    head: [["Date", "Hours", "Water Rate", "Cost", "Notes"]],
    body: data.entries.map((entry) => [
      new Date(entry.date).toLocaleDateString("en-IN"),
      entry.hours.toString(),
      entry.waterRate ? `Rs ${entry.waterRate}` : "-",
      `Rs ${entry.totalAmount.toFixed(2)}`,
      entry.notes || "-",
    ]),
    theme: "grid",
    styles: {
      fontSize: 10,
    },
    headStyles: {
      fillColor: [16, 185, 129], // emerald-500
      fontStyle: "bold",
    },
    alternateRowStyles: {
      fillColor: [248, 250, 252], // slate-50
    },
  });

  // Footer Totals
  // @ts-ignore
  const finalY = doc.lastAutoTable.finalY + 10;

  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text(`Final Total Hours: ${data.totalHours.toFixed(1)} h`, 14, finalY);
  doc.text(`Final Total Cost: Rs ${data.totalAmount.toFixed(2)}`, 14, finalY + 7);

  const pageHeight = doc.internal.pageSize.getHeight();
  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 116, 139);
  doc.text("Generated via Smart Kisan", 14, pageHeight - 10);

  // Preview PDF in new tab
  const pdfBlob = doc.output("blob");
  const pdfUrl = URL.createObjectURL(pdfBlob);

  const previewWindow = window.open(pdfUrl, "_blank");

  if (!previewWindow) {
    alert("Please allow popups to preview the PDF report.");
  }

  // Cleanup Blob URL after some time
  setTimeout(() => {
    URL.revokeObjectURL(pdfUrl);
  }, 10000);
};

export default generateFarmerReportPDF;

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export const generateFieldInsightsPDF = (data: any) => {
  const doc = new jsPDF();

  // Title
  doc.setFontSize(22);
  doc.setTextColor(34, 139, 34); // Forest Green
  doc.text("Field Performance Insights", 14, 20);

  doc.setFontSize(10);
  doc.setTextColor(100, 100, 100);
  doc.text(`Generated on: ${new Date().toLocaleDateString("en-IN")}`, 14, 28);

  // Farm Overview
  doc.setFontSize(16);
  doc.setTextColor(0, 0, 0);
  doc.text("Farm Overview", 14, 40);

  const overviewBody = [
    ["Total Fields", data.overview.totalFields.toString()],
    ["Total Revenue", `Rs. ${data.overview.totalRevenue.toLocaleString()}`],
    ["Total Expenses", `Rs. ${data.overview.totalExpenses.toLocaleString()}`],
    ["Net Profit", `Rs. ${data.overview.netProfit.toLocaleString()}`],
  ];

  autoTable(doc, {
    startY: 45,
    body: overviewBody,
    theme: 'grid',
    styles: { fontSize: 11 },
    columnStyles: { 0: { fontStyle: 'bold', fillColor: [240, 248, 240] } }
  });

  let currentY = (doc as any).lastAutoTable.finalY + 10;

  // Best & Lowest Performers
  if (data.bestField) {
    doc.setFontSize(14);
    doc.text("Best Performing Field", 14, currentY);
    autoTable(doc, {
      startY: currentY + 5,
      body: [
        ["Field", data.bestField.name],
        ["Crop", data.bestField.crop],
        ["Profit", `Rs. ${data.bestField.netProfit.toLocaleString()}`]
      ],
      theme: 'grid',
      styles: { fontSize: 10 }
    });
    currentY = (doc as any).lastAutoTable.finalY + 10;
  }

  // Leaderboard
  doc.setFontSize(14);
  doc.text("Field Performance Leaderboard", 14, currentY);

  const leaderboardBody = data.leaderboard.map((field: any, index: number) => [
    `#${index + 1}`,
    field.name,
    field.crop,
    `Rs. ${field.netProfit.toLocaleString()}`,
    `Rs. ${field.profitPerArea.toLocaleString(undefined, {maximumFractionDigits: 2})}`
  ]);

  autoTable(doc, {
    startY: currentY + 5,
    head: [["Rank", "Field", "Crop", "Net Profit", "Profit/Area"]],
    body: leaderboardBody,
    theme: 'striped',
    headStyles: { fillColor: [34, 139, 34] }
  });

  currentY = (doc as any).lastAutoTable.finalY + 10;

  // Expense Breakdown
  if (currentY > 250) {
    doc.addPage();
    currentY = 20;
  }

  doc.setFontSize(14);
  doc.text("Expense Breakdown", 14, currentY);
  autoTable(doc, {
    startY: currentY + 5,
    head: [["Category", "Amount (Rs.)"]],
    body: [
      ["Water", data.expenses.water.toLocaleString()],
      ["Fertilizer", data.expenses.fertilizer.toLocaleString()],
      ["Labour", data.expenses.labour.toLocaleString()],
      ["Equipment", data.expenses.equipment.toLocaleString()],
    ],
    theme: 'grid'
  });
  currentY = (doc as any).lastAutoTable.finalY + 10;

  // Crop Profitability
  if (currentY > 250) {
    doc.addPage();
    currentY = 20;
  }

  doc.setFontSize(14);
  doc.text("Crop Profitability", 14, currentY);

  const cropBody = Object.entries(data.cropStats).map(([crop, stats]: [string, any]) => [
    crop,
    stats.count.toString(),
    `Rs. ${stats.revenue.toLocaleString()}`,
    `Rs. ${stats.expenses.toLocaleString()}`,
    `Rs. ${stats.profit.toLocaleString()}`
  ]);

  autoTable(doc, {
    startY: currentY + 5,
    head: [["Crop", "Fields", "Revenue", "Expenses", "Net Profit"]],
    body: cropBody,
    theme: 'striped',
    headStyles: { fillColor: [46, 139, 87] }
  });

  currentY = (doc as any).lastAutoTable.finalY + 10;

  // Recommendations
  if (data.recommendations && data.recommendations.length > 0) {
    if (currentY > 230) {
      doc.addPage();
      currentY = 20;
    }

    doc.setFontSize(14);
    doc.text("Smart Farm Recommendations", 14, currentY);

    doc.setFontSize(11);
    doc.setTextColor(50, 50, 50);
    let recY = currentY + 10;

    data.recommendations.forEach((rec: string) => {
      const splitText = doc.splitTextToSize(`• ${rec}`, 180);
      doc.text(splitText, 14, recY);
      recY += splitText.length * 6 + 2;
    });
  }

  // Save/Preview
  const pdfBlob = doc.output("blob");
  const pdfUrl = URL.createObjectURL(pdfBlob);
  const previewWindow = window.open(pdfUrl, "_blank");

  if (!previewWindow) {
    alert("Please allow popups to preview the PDF report.");
  }

  setTimeout(() => {
    URL.revokeObjectURL(pdfUrl);
  }, 10000);
};

